    "template": {
      "spec": {
        "containers": [
          {
            "name": "app",
            "image": "nginx:1.31.5",
            "resources": {
              "limits": {
                "cpu": "3000m",
                "memory": "4Gi"
              },
              "requests": {
                "cpu": "2000m",
                "memory": "2Gi"
              }
            },
            "command": ["nginx", "-g", "daemon off;"],
            "livenessProbe": {
              "initialDelaySeconds": 15,
              "periodSeconds": 15,
              "httpGet": {
                "path": "/",
